struct Buf { n: i64 }
struct Log { n: i64 }
impl Buf { fn len(self) -> i64 { return self.n; } }
impl Log { fn len(self) -> i64 { return self.n; } }
fn main() { let b: Buf = Buf { n: 1 }; let g: Log = Log { n: 2 }; b.len(); }

fn target() -> i64 { return 1; }
fn other() -> i64 { return 2; }
fn run(f: fn() -> i64, g: fn() -> i64) -> i64 { return f() + g(); }
fn main() { run(target, other); }
